1	package numeric
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// writeRawJSONRecord 把一段原始 JSON 直接写成作业记录文件，用于构造
12	// encodeRecord 不会产出的形态（values 字段缺省、空数组等）。
13	func writeRawJSONRecord(t *testing.T, dir string, id uint64, jsonText string) {
14		t.Helper()
15		if err := writeFileAtomic(dir, jobFileName(id), []byte(jsonText), 0o600); err != nil {
16			t.Fatal(err)
17		}
18	}
19	
20	// assertEmptyValuesFailure 校验空原始序列排队记录重开后的统一形态：失败、
21	// BlockerID 为 0、无成功归档与实际输入、从未进入运行，原因明确说明原始整数
22	// 序列为空；原作业号、提交人、请求号、种子、提交时间与依赖顺序保持不变；
23	// 按作业号读取与按提交人列举一致，落盘记录同样已改写。
24	func assertEmptyValuesFailure(t *testing.T, s *Store, id uint64, wantQueuedAt time.Time, wantDeps []uint64) {
25		t.Helper()
26		g, err := s.Get(id)
27		if err != nil {
28			t.Fatal(err)
29		}
30		if g.Status != StatusFailed {
31			t.Fatalf("job %d must fail on empty original values, got %s", id, g.Status)
32		}
33		if g.BlockerID != 0 {
34			t.Fatalf("empty original values is the job's own error: job %d blocker=%d want 0", id, g.BlockerID)
35		}
36		if !strings.Contains(g.FailureReason, "原始整数序列为空") {
37			t.Fatalf("job %d reason=%q must state the original integer sequence is empty", id, g.FailureReason)
38		}
39		if g.Archive != nil || g.EffectiveValues != nil {
40			t.Fatalf("job %d must not return archive/effective inputs: archive=%v effective=%v",
41				id, g.Archive, g.EffectiveValues)
42		}
43		if !g.StartedAt.IsZero() {
44			t.Fatalf("job %d must never start computing, started=%s", id, g.StartedAt)
45		}
46		if g.FinishedAt.IsZero() {
47			t.Fatalf("job %d failed record must carry a finished time", id)
48		}
49		if !g.QueuedAt.Equal(wantQueuedAt) {
50			t.Fatalf("job %d queued time changed: %s want %s", id, g.QueuedAt, wantQueuedAt)
51		}
52		if len(g.Values) != 0 {
53			t.Fatalf("job %d original values must stay empty, got %v", id, g.Values)
54		}
55		if len(g.Dependencies) != len(wantDeps) {
56			t.Fatalf("job %d dependencies changed: %v want %v", id, g.Dependencies, wantDeps)
57		}
58		for i := range wantDeps {
59			if g.Dependencies[i] != wantDeps[i] {
60				t.Fatalf("job %d dependency order changed: %v want %v", id, g.Dependencies, wantDeps)
61			}
62		}
63	
64		listed, err := s.List(g.Submitter, time.Time{}, time.Time{})
65		if err != nil {
66			t.Fatal(err)
67		}
68		found := false
69		for _, lj := range listed {
70			if lj.ID != id {
71				continue
72			}
73			found = true
74			if lj.Status != StatusFailed || lj.BlockerID != 0 ||
75				lj.Archive != nil || lj.EffectiveValues != nil ||
76				lj.FailureReason != g.FailureReason || !lj.FinishedAt.Equal(g.FinishedAt) {
77				t.Fatalf("listed job %d disagrees with Get: status=%s blocker=%d reason=%q",
78					id, lj.Status, lj.BlockerID, lj.FailureReason)
79			}
80		}
81		if !found {
82			t.Fatalf("job %d missing from submitter listing", id)
83		}
84	
85		data, err := os.ReadFile(filepath.Join(s.Dir(), jobFileName(id)))
86		if err != nil {
87			t.Fatal(err)
88		}
89		text := string(data)
90		if !strings.Contains(text, `"status": "failed"`) {
91			t.Fatalf("job %d on-disk record must be failed:\n%s", id, text)
92		}
93		// blocker 为 0 时按 omitempty 不落盘；出现任何 blocker_id 都说明根因错误。
94		if strings.Contains(text, `"blocker_id"`) {
95			t.Fatalf("job %d on-disk record must have no blocker root:\n%s", id, text)
96		}
97		if strings.Contains(text, `"archive"`) {
98			t.Fatalf("job %d on-disk record must not retain archive:\n%s", id, text)
99		}
100		if !strings.Contains(text, `"finished_at"`) {
101			t.Fatalf("job %d on-disk record must carry a finished time:\n%s", id, text)
102		}
103	}
104	
105	// 无依赖的排队记录原始序列为空（values 缺省、为 null 或为空数组）时，重开后
106	// 直接失败——不能继续计算得到总和、平方和均为 0 的成功归档；同目录其他原始
107	// 序列有效的作业照常调度计算，单条无效记录不影响归档打开。
108	func TestReopenQueuedEmptyValuesFailsWithoutComputing(t *testing.T) {
109		dir := t.TempDir()
110		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
111		// 作业 1：values 字段缺省。
112		writeRawJSONRecord(t, dir, 1, `{
113	  "version": "numeric-job-v1",
114	  "id": 1,
115	  "submitter": "a",
116	  "request_id": "missing",
117	  "seed": 7,
118	  "queued_at": "`+base.Add(time.Second).Format(time.RFC3339Nano)+`",
119	  "status": "queued"
120	}`)
121		// 作业 2：values 为 null（encodeRecord 对空序列的既有写法）。
122		writeSyntheticRecord(t, dir, &storedJob{
123			id: 2, submitter: "a", requestID: "null",
124			seed:     8,
125			queuedAt: base.Add(2 * time.Second),
126			status:   StatusQueued,
127		})
128		// 作业 3：values 为空数组。
129		writeRawJSONRecord(t, dir, 3, `{
130	  "version": "numeric-job-v1",
131	  "id": 3,
132	  "submitter": "b",
133	  "request_id": "empty-array",
134	  "seed": 9,
135	  "values": [],
136	  "queued_at": "`+base.Add(3*time.Second).Format(time.RFC3339Nano)+`",
137	  "status": "queued"
138	}`)
139		// 作业 4：原始序列有效的排队作业，重开后应照常完成。
140		writeSyntheticRecord(t, dir, &storedJob{
141			id: 4, submitter: "b", requestID: "indep",
142			values:   []int64{1, 2, 3},
143			queuedAt: base.Add(4 * time.Second),
144			status:   StatusQueued,
145		})
146	
147		s, err := Open(dir)
148		if err != nil {
149			t.Fatal(err)
150		}
151		defer s.Close()
152	
153		assertEmptyValuesFailure(t, s, 1, base.Add(time.Second), nil)
154		assertEmptyValuesFailure(t, s, 2, base.Add(2*time.Second), nil)
155		assertEmptyValuesFailure(t, s, 3, base.Add(3*time.Second), nil)
156		for _, id := range []uint64{1, 2, 3} {
157			g, _ := s.Get(id)
158			if g.Seed != int64(6+id) {
159				t.Fatalf("job %d seed changed: %d", id, g.Seed)
160			}
161		}
162	
163		// 无关的有效作业继续遵守已有调度与计算行为。
164		indep := waitStatus(t, s, 4, StatusSucceeded)
165		if indep.Archive.Sum != 6 || indep.Archive.SumOfSquares != 14 {
166			t.Fatalf("unrelated job result=%d,%d want 6,14", indep.Archive.Sum, indep.Archive.SumOfSquares)
167		}
168	
169		// 再次重开：失败结果已保存在目录中，状态、原因与根因保持稳定。
170		if err := s.Close(); err != nil {
171			t.Fatal(err)
172		}
173		s2, err := Open(dir)
174		if err != nil {
175			t.Fatal(err)
176		}
177		defer s2.Close()
178		assertEmptyValuesFailure(t, s2, 1, base.Add(time.Second), nil)
179		assertEmptyValuesFailure(t, s2, 2, base.Add(2*time.Second), nil)
180		assertEmptyValuesFailure(t, s2, 3, base.Add(3*time.Second), nil)
181	}
182	
183	// 带合法依赖的排队记录原始序列为空时，同样直接失败：不能凭成功上游追加的
184	// 总和补出原始参数后继续计算；被引用的有效上游保留自己的结果。
185	func TestReopenQueuedEmptyValuesWithDependencyFails(t *testing.T) {
186		dir := t.TempDir()
187		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
188		// 作业 1：[1,2] → 总和 3，成功归档。
189		up := syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
190		if up.archive.Sum != 3 {
191			t.Fatalf("upstream sum=%d want 3", up.archive.Sum)
192		}
193		// 作业 2：排队，原始序列为空，合法依赖作业 1。若凭上游总和补出输入，
194		// 会以 [3] 算出总和 3、平方和 9 的“成功”结果——必须拒绝。
195		writeSyntheticRecord(t, dir, &storedJob{
196			id: 2, submitter: "a", requestID: "empty",
197			dependencies: []uint64{1},
198			queuedAt:     base.Add(2 * time.Second),
199			status:       StatusQueued,
200		})
201	
202		s, err := Open(dir)
203		if err != nil {
204			t.Fatal(err)
205		}
206		defer s.Close()
207	
208		assertEmptyValuesFailure(t, s, 2, base.Add(2*time.Second), []uint64{1})
209	
210		// 被引用的有效上游保留自己的成功结果，不因无效记录而改变。
211		gUp, _ := s.Get(1)
212		if gUp.Status != StatusSucceeded || gUp.Archive == nil || gUp.Archive.Sum != 3 {
213			t.Fatalf("valid upstream must keep its result: status=%s archive=%v", gUp.Status, gUp.Archive)
214		}
215	}
216	
217	// 等待空序列记录结果的下游按既有依赖失败规则被阻断：原因指出直接阻断它的
218	// 上游，根因沿依赖链保留为空序列记录自身的作业号；再下游沿链条继承同一根因。
219	func TestReopenQueuedEmptyValuesBlocksDownstream(t *testing.T) {
220		dir := t.TempDir()
221		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
222		// 作业 1：排队，原始序列为空。
223		writeSyntheticRecord(t, dir, &storedJob{
224			id: 1, submitter: "a", requestID: "empty",
225			queuedAt: base.Add(time.Second),
226			status:   StatusQueued,
227		})
228		// 作业 2：排队等待作业 1。
229		writeSyntheticRecord(t, dir, &storedJob{
230			id: 2, submitter: "a", requestID: "child",
231			values:       []int64{20},
232			dependencies: []uint64{1},
233			queuedAt:     base.Add(2 * time.Second),
234			status:       StatusQueued,
235		})
236		// 作业 3：排队等待作业 2（空序列记录的再下游）。
237		writeSyntheticRecord(t, dir, &storedJob{
238			id: 3, submitter: "a", requestID: "grandchild",
239			values:       []int64{30},
240			dependencies: []uint64{2},
241			queuedAt:     base.Add(3 * time.Second),
242			status:       StatusQueued,
243		})
244	
245		s, err := Open(dir)
246		if err != nil {
247			t.Fatal(err)
248		}
249		defer s.Close()
250	
251		assertEmptyValuesFailure(t, s, 1, base.Add(time.Second), nil)
252	
253		child := waitStatus(t, s, 2, StatusFailed)
254		if child.BlockerID != 1 {
255			t.Fatalf("child blocker=%d want root 1 (the empty-values record itself)", child.BlockerID)
256		}
257		if !strings.Contains(child.FailureReason, "直接上游作业 1") ||
258			!strings.Contains(child.FailureReason, "原始整数序列为空") {
259			t.Fatalf("child must name direct upstream 1 and carry its empty-values reason: %q",
260				child.FailureReason)
261		}
262		if child.Archive != nil || !child.StartedAt.IsZero() {
263			t.Fatalf("blocked child must never compute: started=%s archive=%v", child.StartedAt, child.Archive)
264		}
265	
266		grand := waitStatus(t, s, 3, StatusFailed)
267		if grand.BlockerID != 1 {
268			t.Fatalf("grandchild blocker=%d want root 1 preserved along the chain", grand.BlockerID)
269		}
270		if !strings.Contains(grand.FailureReason, "直接上游作业 2") ||
271			!strings.Contains(grand.FailureReason, "阻断根因为作业 1") {
272			t.Fatalf("grandchild must name direct upstream 2 and root 1: %q", grand.FailureReason)
273		}
274	}
275	
276	// 空序列指没有任何原始整数：[0]、[0,0] 以及包含负数或重复整数的非空序列
277	// 仍是合法输入，不按总和是否为 0 判断有效性，重开后照常计算成功。
278	func TestReopenQueuedZeroValuedSequencesRemainValid(t *testing.T) {
279		dir := t.TempDir()
280		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
281		writeSyntheticRecord(t, dir, &storedJob{
282			id: 1, submitter: "a", requestID: "zero",
283			values:   []int64{0},
284			queuedAt: base.Add(time.Second),
285			status:   StatusQueued,
286		})
287		writeSyntheticRecord(t, dir, &storedJob{
288			id: 2, submitter: "a", requestID: "zeros",
289			values:   []int64{0, 0},
290			queuedAt: base.Add(2 * time.Second),
291			status:   StatusQueued,
292		})
293		writeSyntheticRecord(t, dir, &storedJob{
294			id: 3, submitter: "a", requestID: "neg-dup",
295			values:   []int64{-2, 2, -2},
296			queuedAt: base.Add(3 * time.Second),
297			status:   StatusQueued,
298		})
299	
300		s, err := Open(dir)
301		if err != nil {
302			t.Fatal(err)
303		}
304		defer s.Close()
305	
306		g1 := waitStatus(t, s, 1, StatusSucceeded)
307		if g1.Archive.Sum != 0 || g1.Archive.SumOfSquares != 0 {
308			t.Fatalf("[0] result=%d,%d want 0,0", g1.Archive.Sum, g1.Archive.SumOfSquares)
309		}
310		g2 := waitStatus(t, s, 2, StatusSucceeded)
311		if g2.Archive.Sum != 0 || g2.Archive.SumOfSquares != 0 {
312			t.Fatalf("[0,0] result=%d,%d want 0,0", g2.Archive.Sum, g2.Archive.SumOfSquares)
313		}
314		g3 := waitStatus(t, s, 3, StatusSucceeded)
315		if g3.Archive.Sum != -2 || g3.Archive.SumOfSquares != 12 {
316			t.Fatalf("[-2,2,-2] result=%d,%d want -2,12", g3.Archive.Sum, g3.Archive.SumOfSquares)
317		}
318	}
319	
320	// 已经失败或取消的记录即使原始序列为空，也保留既有终态、原因与根因，
321	// 不被恢复阶段的空序列检查改写。
322	func TestReopenEmptyValuesKeepsExistingTerminalRecords(t *testing.T) {
323		dir := t.TempDir()
324		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
325		failedAt := base.Add(2 * time.Second)
326		writeSyntheticRecord(t, dir, &storedJob{
327			id: 1, submitter: "a", requestID: "f",
328			queuedAt: failedAt, finishedAt: failedAt,
329			status:        StatusFailed,
330			failureReason: "既有的失败原因",
331			blockerID:     9,
332		})
333		writeSyntheticRecord(t, dir, &storedJob{
334			id: 2, submitter: "a", requestID: "c",
335			queuedAt: base.Add(3 * time.Second), finishedAt: base.Add(4 * time.Second),
336			status: StatusCanceled,
337		})
338	
339		s, err := Open(dir)
340		if err != nil {
341			t.Fatal(err)
342		}
343		defer s.Close()
344	
345		gf, _ := s.Get(1)
346		if gf.Status != StatusFailed || gf.BlockerID != 9 || gf.FailureReason != "既有的失败原因" {
347			t.Fatalf("existing failed record must be preserved: status=%s blocker=%d reason=%q",
348				gf.Status, gf.BlockerID, gf.FailureReason)
349		}
350		gc, _ := s.Get(2)
351		if gc.Status != StatusCanceled || gc.BlockerID != 0 || gc.FailureReason != "" {
352			t.Fatalf("existing canceled record must be preserved: status=%s blocker=%d reason=%q",
353				gc.Status, gc.BlockerID, gc.FailureReason)
354		}
355	}
