551	func TestCancelQueuedAndRunningAndCascade(t *testing.T) {
552		s, _ := openTestStore(t)
553		started, block, release, _, _ := gateCompute(t, s)
554		block(1)
555	
556		first := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
557		waitStarted(t, started, first.ID)
558	
559		mid := mustSubmit(t, s, SubmitRequest{ // 等 first 的结果
560			Submitter: "a", Values: []int64{2},
561			HasDependency: true, DependencyID: first.ID,
562		})
563		far := mustSubmit(t, s, SubmitRequest{ // 等 mid
564			Submitter: "a", Values: []int64{3},
565			HasDependency: true, DependencyID: mid.ID,
566		})
567		independent := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{9}})
568		// 此时唯一位置被 id 1 占用，mid/far 等依赖、independent 等位置。
569	
570		// 取消运行中的 first。
571		cj, err := s.Cancel(first.ID)
572		if err != nil || cj.Status != StatusCanceled {
573			t.Fatalf("cancel running: %v %+v", err, cj)
574		}
575		// 重复取消仍成功。
576		if again, err := s.Cancel(first.ID); err != nil || again.Status != StatusCanceled {
577			t.Fatalf("repeat cancel: %v %+v", err, again)
578		}
579		release(first.ID) // 放行计算，成功结果必须被丢弃
580	
581		mm := waitStatus(t, s, mid.ID, StatusFailed)
582		ff := waitStatus(t, s, far.ID, StatusFailed)
583		// independent 未被等待依赖的 mid/far 堵在后面，照常成功。
584		ind := waitStatus(t, s, independent.ID, StatusSucceeded)
585		if ind.Archive.Sum != 9 {
586			t.Fatalf("independent sum=%d want 9", ind.Archive.Sum)
587		}
588		if mm.BlockerID != first.ID || ff.BlockerID != first.ID {
589			t.Fatalf("cascade blockers %d,%d want root %d", mm.BlockerID, ff.BlockerID, first.ID)
590		}
591		if mm.Archive != nil || ff.Archive != nil {
592			t.Fatal("canceled job and dependents must never archive success")
593		}
594		if !strings.Contains(mm.FailureReason, "取消") || !strings.Contains(ff.FailureReason, "阻断") {
595			t.Fatalf("failure reasons must explain the blocker: mid=%q far=%q", mm.FailureReason, ff.FailureReason)
596		}
597	
598		// 已成功的作业不能取消，结果保持。
599		if _, err := s.Cancel(independent.ID); !errors.Is(err, ErrNotCancellable) {
600			t.Fatalf("cancel succeeded: %v, want ErrNotCancellable", err)
601		}
602		got, _ := s.Get(independent.ID)
603		if got.Status != StatusSucceeded || got.Archive == nil {
604			t.Fatal("succeeded result changed after rejected cancel")
605		}
606		// 已失败的作业同样不能取消，原因保持。
607		if _, err := s.Cancel(mm.ID); !errors.Is(err, ErrNotCancellable) {
608			t.Fatalf("cancel failed: %v", err)
609		}
610		got2, _ := s.Get(mm.ID)
611		if got2.Status != StatusFailed || got2.FailureReason != mm.FailureReason {
612			t.Fatal("failed record changed after rejected cancel")
613		}
614	}
